55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	/**
65	 * Insurance values are distinct from base premiums: they size the payout cap,
66	 * not the price. Component block discounts affect the premium only, never the
67	 * insurance sum, so this table is always applied per individual item.
68	 */
69	const INSURANCE_VALUES: Record<string, number> = {
70	  sword: 1000,
71	  amulet: 600,
72	  staff: 800,
73	  potion: 400,
74	  rune: 250,
75	  moonstone: 250,
76	};
77	
78	const DEDUCTIBLE_PER_DAMAGE = 100;
79	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
80	
81	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
82	const PROCESSING_FEE = 5;
83	
84	const HUNDRED = 100;
85	
86	/**
87	 * The value of a percentage of an amount. Modifiers are summed as separate
88	 * amounts rather than compounded, so each is computed against its own base:
89	 * a cursed sword is 100 + 50 % of 100 + 10 % of 100, not 100 × 1.5 × 1.1.
90	 *
91	 * Multiplies before dividing, keeping the percentage an integer ratio rather
92	 * than a decimal factor: 100 * 1.1 === 110.00000000000001 in binary floating
93	 * point, which would round the wrong way. Intermediates stay exact and only
94	 * the final premium is rounded.
95	 */
96	const percentOf = (amount: number, percent: number): number =>
97	  (amount * percent) / HUNDRED;
98	
99	/**
100	 * Both roundings are in the MHPCO's favour, which is why they run in OPPOSITE
101	 * directions: the office keeps the fraction either way, charging the most and
102	 * paying the least the amount allows. Read either function alone and the pair
103	 * looks inconsistent; the rule is the favour, not the direction.
104	 *
105	 * They stay two functions rather than one parameterised by direction. "Round
106	 * up" and "round down" share a motive, not an implementation, and collapsing
107	 * them would put a conditional where there is now a single Math call.
108	 */
109	const roundPremium = (amount: number): number => Math.ceil(amount);
110	
111	const roundPayout = (amount: number): number => Math.floor(amount);
112	
113	const basePremiumOfType = (type: string): number => {
114	  const basePremium = BASE_PREMIUMS[type];
115	  if (basePremium === undefined) {
116	    // The spec rejects a quote containing an unknown item type outright, but
117	    // no active test pins the error behaviour yet. Fail loudly rather than
118	    // silently pricing an unknown item at zero, which the spec contradicts.
119	    throw new Error(`Unknown item type: ${type}`);
120	  }
121	  return basePremium;
122	};
123	
124	/** Component types are sold individually or as a block of alike pieces. */
125	const COMPONENT_TYPES = ["rune", "moonstone"];
126	const COMPONENT_BLOCK_SIZE = 3;
127	const COMPONENT_BLOCK_PREMIUM = 60;
128	
129	const countByType = (items: Item[]): Map<string, number> => {
130	  const counts = new Map<string, number>();
131	  for (const item of items) {
132	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
133	  }
134	  return counts;
135	};
136	
137	/**
138	 * Base premium for a group of alike items. A block rate applies only when a
139	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
140	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
141	 */
142	const basePremiumOfGroup = (type: string, count: number): number => {
143	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
144	    return COMPONENT_BLOCK_PREMIUM;
145	  }
146	  return count * basePremiumOfType(type);
147	};
148	
149	const CURSE_SURCHARGE_PERCENT = 50;
150	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
151	const HIGH_ENCHANTMENT_MIN_LEVEL = 5;
152	
153	/**
154	 * Whether an item carries an enchantment at or above the surcharge threshold.
155	 * Components (runes, moonstones) have no enchantment field at all; an absent
156	 * enchantment is not a level of 0, it is the absence of the property, and so
157	 * never qualifies. Stated as an explicit undefined check rather than a numeric
158	 * default so the reason reads as "unenchanted", not "enchanted to zero".
159	 */
160	const isHighlyEnchanted = (item: Item): boolean =>
161	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_MIN_LEVEL;
162	
163	/**
164	 * Item-specific surcharges are a percentage of the affected item's OWN base
165	 * premium, not of the policy total. They are summed alongside the policy-wide
166	 * modifiers rather than compounded with them, so an item that is both cursed
167	 * and highly enchanted carries base + 50 % of base + 30 % of base.
168	 *
169	 * KNOWN GAP: basePremiumOfType gives the item's standalone base, which differs
170	 * from its share of a component block — a rune in a block of 3 is charged 20,
171	 * not 25, so a cursed or highly enchanted rune inside a block would surcharge
172	 * against 25. This affects both surcharge terms, not just the curse. Left as
173	 * is deliberately: the spec defines neither cursed nor enchanted components,
174	 * gives no rule for apportioning a block rate across its pieces, and no test
175	 * pins the behaviour. Resolve it when a test forces a choice, not before.
176	 */
177	const itemSurchargeOf = (item: Item): number => {
178	  const itemBase = basePremiumOfType(item.type);
179	  const curseSurcharge =
180	    item.cursed === true ? percentOf(itemBase, CURSE_SURCHARGE_PERCENT) : 0;
181	  const enchantmentSurcharge = isHighlyEnchanted(item)
182	    ? percentOf(itemBase, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
183	    : 0;
184	  return curseSurcharge + enchantmentSurcharge;
185	};
186	
187	const LOYALTY_DISCOUNT_PERCENT = 20;
188	const LOYALTY_MIN_YEARS = 2;
189	
190	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
191	
192	/**
193	 * Quotes are numbered from this ordinal; every quote after it is a follow-up
194	 * contract. The ordinal counts QUOTE steps only — claim steps interleave with
195	 * quotes in a scenario and must not advance the contract count.
196	 */
197	const FIRST_QUOTE_ORDINAL = 0;
198	
199	/** Long-standing customers qualify from exactly LOYALTY_MIN_YEARS onwards. */
200	const isLongStanding = (customer: Customer): boolean =>
201	  customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS;
202	
203	/** Every contract after the customer's first one in the scenario. */
204	const isFollowUpContract = (quoteOrdinal: number): boolean =>
205	  quoteOrdinal > FIRST_QUOTE_ORDINAL;
206	
207	/** Policy base premium: every group's base, before any modifier. */
208	const policyBaseOf = (items: Item[]): number =>
209	  [...countByType(items)].reduce(
210	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
211	    0,
212	  );
213	
214	const itemSurchargesOf = (items: Item[]): number =>
215	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
216	
217	/**
218	 * The net of the policy-wide modifiers: surcharges positive, discounts
219	 * negative. Each is a percentage of the POLICY base and they are summed, never
220	 * compounded — a long-standing customer's first insurance is +10 % and -20 % of
221	 * the same base, a net -10 %, not 1.1 × 0.8.
222	 */
223	const policyModifiersOf = (
224	  policyBase: number,
225	  customer: Customer,
226	  quoteOrdinal: number,
227	): number => {
228	  const firstInsuranceSurcharge = percentOf(
229	    policyBase,
230	    FIRST_INSURANCE_SURCHARGE_PERCENT,
231	  );
232	  const loyaltyDiscount = isLongStanding(customer)
233	    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
234	    : 0;
235	  const followUpDiscount = isFollowUpContract(quoteOrdinal)
236	    ? percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
237	    : 0;
238	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
239	};
240	
241	const quoteResult = (
242	  items: Item[],
243	  customer: Customer,
244	  quoteOrdinal: number,
245	): QuoteResult => {
246	  const policyBase = policyBaseOf(items);
247	  const premium =
248	    policyBase +
249	    itemSurchargesOf(items) +
250	    policyModifiersOf(policyBase, customer, quoteOrdinal) +
251	    PROCESSING_FEE;
252	  return { premium: roundPremium(premium) };
253	};
254	
255	/** A quote step's policy, carried forward so later claims can draw on it. */
256	interface Policy {
257	  items: Item[];
258	  remainingCap: number;
259	}
260	
261	const policyFor = (items: Item[]): Policy => {
262	  const insuranceSum = items.reduce(
263	    (total, item) => total + (INSURANCE_VALUES[item.type] ?? 0),
264	    0,
265	  );
266	  return {
267	    items,
268	    remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum,
269	  };
270	};
271	
272	const HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL = 8;
273	const HIGH_ENCHANTMENT_CLAUSE_PERCENT = 50;
274	
275	/**
276	 * The damaged item, located by type. A damage entry names a TYPE, not a
277	 * particular item, so a policy holding two swords of different enchantments is
278	 * ambiguous; the spec offers no tie-break, so the first match wins.
279	 */
280	const damagedItem = (damage: Damage, items: Item[]): Item | undefined =>
281	  items.find((item) => item.type === damage.itemType);
282	
283	/**
284	 * One damage event. A special clause reduces the reimbursed amount BEFORE the
285	 * deductible is taken: an item enchanted to HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
286	 * or above is reimbursed at half, so 1000 becomes 500 and then 400 — not
287	 * (1000 - 100) halved.
288	 *
289	 * DRAGON MATERIAL, deliberately unexpressed. The spec states a second clause —
290	 * damage to dragon-material items is FULLY reimbursed — which this function
291	 * never mentions. That is considered, not overlooked. Full reimbursement is
292	 * already the default path when no clause fires, so a dragon branch returning
293	 * damage.amount would be a branch no test could ever distinguish from its own
294	 * absence. The three spec cases pass unchanged: dragon/ench 8/1000 -> 400,
295	 * dragon/ench 5/800 -> 700, dragon/ench 9/1000 -> 400.
296	 *
297	 * The clauses also do not conflict in the way "both apply" suggests. Where an
298	 * item is both dragon and enchanted >= 8, the spec has the 50 % rule WIN — so
299	 * the enchantment check above is not merely first, it is correct to be the
300	 * only check. Should a later rule ever make full reimbursement differ from the
301	 * default (a cap interaction, say), this clause must become explicit.
302	 */
303	const payoutForDamage = (damage: Damage, items: Item[]): number => {
304	  const item = damagedItem(damage, items);
305	  const enchantment = item?.enchantment;
306	  const reimbursed =
307	    enchantment !== undefined &&
308	    enchantment >= HIGH_ENCHANTMENT_CLAUSE_MIN_LEVEL
309	      ? percentOf(damage.amount, HIGH_ENCHANTMENT_CLAUSE_PERCENT)
310	      : damage.amount;
311	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
312	};
313	
314	/**
315	 * A policy pays at most what its cap has left, so a claim beyond the cap is
316	 * reduced to the remainder and an exhausted policy pays nothing — the cap lands
317	 * on 0 rather than going negative. The spec's own phrasing: "the desired 1400 G
318	 * is reduced to the remaining cap".
319	 */
320	const reducedToRemainingCap = (desired: number, remainingCap: number): number =>
321	  Math.min(desired, remainingCap);
322	
323	/**
324	 * How many items of each type an incident reports damaged.
325	 *
326	 * Deliberately NOT unified with countByType, whose body is structurally the
327	 * same. The two answer different questions — what a policy INSURES versus what
328	 * an incident REPORTS — and they key on separately named schema fields for that
329	 * reason. They share the Map-increment idiom, not a rule: a change to how
330	 * blocks group insured items rewrites countByType alone, and a change to how
331	 * repeated entries count as one damage rewrites this one alone. Extracting a
332	 * generic countBy would unify them only where they agree by accident.
333	 */
334	const countDamagesByType = (damages: Damage[]): Map<string, number> => {
335	  const counts = new Map<string, number>();
336	  for (const damage of damages) {
337	    counts.set(damage.itemType, (counts.get(damage.itemType) ?? 0) + 1);
338	  }
339	  return counts;
340	};
341	
342	/**
343	 * A claim may not report more damaged items of a type than the policy covers.
344	 * The whole claim is rejected, so this runs before any payout is computed and
345	 * before the cap is touched — a policy must not be partially drawn down by a
346	 * claim that is about to be refused. Counting is per claim: successive claims
347	 * against the same policy each get the full complement of insured items.
348	 *
349	 * This ONE guard settles two of the spec's rules, which are one rule counted.
350	 * A damage naming a type the policy does not hold — an amulet when only a
351	 * sword is insured, or an outright unknown type — is covered 0 and damaged 1,
352	 * so it is rejected here by the same comparison. The spec states both in a
353	 * single breath ("not part of the policy ... or an item with an unknown
354	 * type"), so encoding them as one comparison is the honest reading rather than
355	 * a coincidence; a separate uncovered-type check would be a second spelling of
356	 * this one. Hence the message names counts rather than asserting an overcount:
357	 * it has to read correctly when `covered` is 0.
358	 *
359	 * A void guard, not a predicate. The codebase's is* functions return booleans
360	 * to be read inside expressions; this is executed for its effect, and naming it
361	 * isOvercounted would promise a value it does not produce. Keeping the
362	 * rejection out of claimOutcome's arithmetic is what lets that arithmetic stay
363	 * a pure expression with no error case threaded through it.
364	 */
365	const rejectOvercountedDamages = (incident: Incident, policy: Policy): void => {
366	  const insured = countByType(policy.items);
367	  for (const [itemType, damaged] of countDamagesByType(incident.damages)) {
368	    const covered = insured.get(itemType) ?? 0;
369	    if (damaged > covered) {
