377	/**
378	 * A claim's effect on its policy: what is paid now and what the policy has
379	 * left afterwards. Pure — the caller is responsible for storing the new
380	 * remaining cap, so the arithmetic can be read without tracing who mutated
381	 * what.
382	 *
383	 * Clip THEN round, and not the other way about. The desired total can be
384	 * fractional, so rounding it before the clip would report a remaining cap the
385	 * payout never justified. The two calls are left nested for that reason: the
386	 * order is load-bearing, and nesting makes it structural rather than a
387	 * sequence of bindings that a later edit could reorder or mis-wire.
388	 */
389	/**
390	 * Damage is a loss, never a credit. Left unchecked a negative amount pays a
391	 * negative payout and, because the cap subtracts that payout, RAISES the
392	 * remaining cap above the value the policy was written for.
393	 *
394	 * Only negatives are refused. A zero amount is arguably as meaningless, but the
395	 * spec names `amount: -200` and says nothing about 0, so rejecting 0 would be
396	 * inventing a rule rather than enforcing one.
397	 *
398	 * Like the overcount guard this runs before any arithmetic: the whole claim is
399	 * refused, so the policy must not be drawn down on the way to refusing it.
400	 */
401	const rejectNegativeDamages = (incident: Incident): void => {
402	  for (const damage of incident.damages) {
403	    if (damage.amount < 0) {
404	      throw new Error(
405	        `Claim reports a negative amount ${damage.amount} for "${damage.itemType}"`,
406	      );
407	    }
408	  }
409	};
410	
411	const claimOutcome = (incident: Incident, policy: Policy): ClaimResult => {
412	  rejectOvercountedDamages(incident, policy);
413	  rejectNegativeDamages(incident);
414	  const desired = incident.damages.reduce(
415	    (total, damage) => total + payoutForDamage(damage, policy.items),
416	    0,
417	  );
418	  const payout = roundPayout(
419	    reducedToRemainingCap(desired, policy.remainingCap),
420	  );
421	  return { payout, remainingCap: policy.remainingCap - payout };
422	};
423	
424	/**
425	 * Where a step sits in the scenario walk. The two ordinals are genuinely
426	 * different facts and must not be collapsed: `index` is the step's own
427	 * zero-based position, which is how a later claim names its policy, while
428	 * `quoteOrdinal` counts QUOTE steps only. In [quote, claim, quote] the last
429	 * step has index 2 but quote ordinal 1 — using either in place of the other
430	 * would misprice the follow-up discount.
431	 */
432	interface StepPosition {
433	  index: number;
434	  quoteOrdinal: number;
435	}
436	
437	/** The mutable state carried along one scenario: the policies quotes create. */
438	interface ScenarioWalk {
439	  customer: Customer;
440	  policies: Map<number, Policy>;
441	}
442	
443	const runStep = (
444	  step: Step,
445	  position: StepPosition,
446	  walk: ScenarioWalk,
447	): StepResult => {
448	  if (step.op === "quote") {
449	    walk.policies.set(position.index, policyFor(step.items));
450	    return quoteResult(step.items, walk.customer, position.quoteOrdinal);
451	  }
452	  const policy = walk.policies.get(step.policy);
453	  if (policy === undefined) {
454	    throw new Error(`No policy created by step ${step.policy}`);
455	  }
456	  const outcome = claimOutcome(step.incident, policy);
457	  policy.remainingCap = outcome.remainingCap;
458	  return outcome;
459	};
460	
461	export const runScenario = (scenario: Scenario): ScenarioResults => {
462	  const walk: ScenarioWalk = {
463	    customer: scenario.customer,
464	    policies: new Map<number, Policy>(),
465	  };
466	  let quoteOrdinal = FIRST_QUOTE_ORDINAL;
467	  const results = scenario.steps.map((step, index) => {
468	    const result = runStep(step, { index, quoteOrdinal }, walk);
469	    if (step.op === "quote") quoteOrdinal += 1;
470	    return result;
471	  });
472	  return { results };
473	};
